import XCTest
@testable import TygerVoice

/// Decision parity for MelFeatures: fixtures generated by running the Python
/// extractor (scripts/tyger-swift-fixtures.py) must be reproduced here.
final class MelFeaturesTests: XCTestCase {
    struct Case: Decodable {
        let name: String
        let audio: [Float]
        let valid: Int
        let sample_idx: [Int]
        let frames: [[Float]]
    }
    struct Fixtures: Decodable { let cases: [Case] }

    func testFeaturesMatchThePythonExtractor() throws {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().appendingPathComponent("fixtures.json")
        let fx = try JSONDecoder().decode(Fixtures.self, from: try Data(contentsOf: url))
        XCTAssertFalse(fx.cases.isEmpty)
        for c in fx.cases {
            let (features, valid) = MelFeatures.process(c.audio)
            XCTAssertEqual(valid, c.valid, "\(c.name): valid frames")
            XCTAssertGreaterThanOrEqual(features.count, (c.sample_idx.last ?? -1) + 1, "\(c.name): frame count")
            for (row, idx) in zip(c.frames, c.sample_idx) {
                for m in 0..<MelFeatures.nMels {
                    let d = abs(features[idx][m] - row[m])
                    XCTAssertLessThan(d, 2e-3, "\(c.name): frame \(idx) mel \(m) swift=\(features[idx][m]) py=\(row[m])")
                }
            }
        }
    }

    func testHannMatchesTorch() {
        // torch.hann_window(400, periodic=False): 0.5*(1-cos(2πn/399)), first/last are 0
        let w = MelFeatures.hannSymmetric(winLength: 400, total: 512)
        XCTAssertEqual(w.count, 512)
        XCTAssertEqual(w[56], 0, accuracy: 1e-6)
        XCTAssertEqual(w[455], 0, accuracy: 1e-6)
        XCTAssertEqual(w[56 + 200], Float(0.5 * (1 - cos(2 * Double.pi * 200 / 399))), accuracy: 1e-6) // midpoint (torch: n=199.5)
    }
}
